import React, { useState, useEffect } from 'react';

const API_BASE = 'http://localhost:5000/api';

function App() {
  const [token, setToken] = useState(localStorage.getItem('plateai_token') || '');
  const [currentUser, setCurrentUser] = useState(JSON.parse(localStorage.getItem('plateai_user') || 'null'));

  const [authMode, setAuthMode] = useState('signin');
  const [emailInput, setEmailInput] = useState('');
  const [passwordInput, setPasswordInput] = useState('');
  const [nameInput, setNameInput] = useState('');
  const [roleInput, setRoleInput] = useState('Admin / Canteen manager');
  const [authError, setAuthError] = useState('');

  const [activeTab, setActiveTab] = useState('demand');
  const [overviewData, setOverviewData] = useState(null);
  const [forecastData, setForecastData] = useState({
    expectedAttendance: 438,
    day: 'Wednesday',
    mealType: 'Lunch',
    safetyBuffer: 15,
    temperature: 28,
    rainfall: 0,
    holiday: false,
    campusEvent: false,
    weatherContext: { temp: 28, condition: 'Demo clear weather', rainfall: '0 mm', humidity: '62%' }
  });

  const [calculatedPlan, setCalculatedPlan] = useState(null);
  const [forecastMessage, setForecastMessage] = useState('');

  const handleLogin = async (e) => {
    e.preventDefault();
    setAuthError('');
    try {
      const res = await fetch(`${API_BASE}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: emailInput, password: passwordInput })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Login failed');
      setToken(data.token);
      setCurrentUser(data.user);
      localStorage.setItem('plateai_token', data.token);
      localStorage.setItem('plateai_user', JSON.stringify(data.user));
    } catch (err) {
      setAuthError(err.message);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setAuthError('');
    try {
      const res = await fetch(`${API_BASE}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: nameInput || 'Maya Sharma', email: emailInput, password: passwordInput, role: 'Admin' })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Registration failed');
      setToken(data.token);
      setCurrentUser(data.user);
      localStorage.setItem('plateai_token', data.token);
      localStorage.setItem('plateai_user', JSON.stringify(data.user));
    } catch (err) {
      setAuthError(err.message);
    }
  };

  const handleDemoAccess = () => {
    fetch(`${API_BASE}/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: 'admin@plateai.com', password: 'password123' })
    })
      .then(res => res.json())
      .then(data => {
        if (data.token) {
          setToken(data.token);
          setCurrentUser(data.user);
          localStorage.setItem('plateai_token', data.token);
          localStorage.setItem('plateai_user', JSON.stringify(data.user));
        }
      }).catch(() => {
        const mockUser = { name: 'Maya Sharma', email: 'admin@plateai.com', role: 'Admin' };
        setToken('demo');
        setCurrentUser(mockUser);
        localStorage.setItem('plateai_token', 'demo');
        localStorage.setItem('plateai_user', JSON.stringify(mockUser));
      });
  };

  const handleLogout = () => {
    setToken('');
    setCurrentUser(null);
    localStorage.removeItem('plateai_token');
    localStorage.removeItem('plateai_user');
  };

  useEffect(() => {
    if (!token) return;
    fetch(`${API_BASE}/overview`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.json())
      .then(setOverviewData)
      .catch(() => {});

    fetch(`${API_BASE}/forecast`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.json())
      .then(data => { if (data) setForecastData(data); })
      .catch(() => {});
  }, [token]);

  const handleCalculateForecast = (e) => {
    e.preventDefault();
    fetch(`${API_BASE}/forecast`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      body: JSON.stringify(forecastData)
    })
      .then(res => res.json())
      .then(data => {
        if (data.success) {
          const attendance = Number(forecastData.expectedAttendance) || 438;
          const buffer = Number(forecastData.safetyBuffer) || 15;
          const predictedDemandVal = Math.round(attendance * 0.93);
          const recommendedPrepVal = predictedDemandVal + buffer;

          setCalculatedPlan({
            predictedDemand: predictedDemandVal,
            recommendedPrep: recommendedPrepVal,
            buffer: buffer,
            day: forecastData.day,
            mealType: forecastData.mealType.toLowerCase(),
            temperature: forecastData.temperature,
            rainfall: forecastData.rainfall,
            planningNote: `Plan for about ${predictedDemandVal} ${forecastData.mealType.toLowerCase()} meals on ${forecastData.day}. Prepare ${recommendedPrepVal} to include the ${buffer}-meal safety buffer. Attendance trends support this estimate, with normal weather and no holiday or event. Action: keep extra rice and one main dish ready for quick top-up if demand rises.`
          });

          setForecastMessage('Preparation plan calculated successfully!');
          setTimeout(() => setForecastMessage(''), 4000);
        }
      }).catch(() => {});
  };

  const handleSyncWeather = async () => {
    try {
      const res = await fetch(`${API_BASE}/weather/live`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      const data = await res.json();

      if (data.success) {
        setForecastData(prev => ({
          ...prev,
          temperature: data.temperature,
          rainfall: parseFloat(data.rainfall) || 0,
          weatherContext: {
            temp: data.temperature,
            condition: data.condition,
            rainfall: data.rainfall,
            humidity: data.humidity
          }
        }));
        setForecastMessage('Live weather synchronized from API successfully!');
      }
    } catch (err) {
      setForecastMessage('Could not reach live weather API. Using current defaults.');
    }
    setTimeout(() => setForecastMessage(''), 4000);
  };

  // --- AUTH SCREEN ---
  if (!token) {
    return (
      <div className="min-h-screen w-full flex flex-col lg:flex-row font-sans bg-white">
        <div className="lg:w-7/12 relative bg-[#142A1E] text-white p-12 flex flex-col justify-between overflow-hidden min-h-[400px] lg:min-h-screen">
          <div className="absolute inset-0 opacity-40 bg-cover bg-center mix-blend-overlay" style={{ backgroundImage: `url('https://images.unsplash.com/photo-1556910103-1c02745aae4d?q=80&w=1200&auto=format&fit=crop')` }} />
          <div className="absolute inset-0 bg-gradient-to-t from-[#142A1E] via-transparent to-transparent" />
          <div className="relative z-10"><p className="text-[11px] font-bold tracking-widest text-[#D1F247] uppercase">PLATEAI · FOOD WITH PURPOSE</p></div>
          <div className="relative z-10 max-w-xl my-auto py-12">
            <h1 className="text-5xl lg:text-7xl font-extrabold tracking-tight mb-6 leading-none">Serve what matters.</h1>
            <p className="text-gray-300 text-base lg:text-lg">A calmer way to plan meals, protect surplus, and move good food to people who need it.</p>
          </div>
          <div className="relative z-10"><p className="text-[11px] tracking-widest text-gray-400 uppercase">SMART CANTEEN OPERATIONS / 01</p></div>
        </div>

        <div className="lg:w-5/12 p-8 lg:p-16 flex flex-col justify-center bg-white">
          <div className="max-w-md w-full mx-auto">
            <p className="text-[11px] font-bold tracking-widest text-[#1A7B48] uppercase mb-2">WORKSPACE ACCESS</p>
            <h2 className="text-3xl font-extrabold text-gray-900 mb-2">Good to see you.</h2>
            <p className="text-sm text-gray-500 mb-8">Run the full canteen-to-community flow from one place.</p>

            <div className="flex bg-gray-100 p-1 rounded-xl mb-8">
              <button type="button" onClick={() => { setAuthMode('signin'); setAuthError(''); }} className={`flex-1 py-2.5 text-xs font-bold rounded-lg ${authMode === 'signin' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500'}`}>Sign in</button>
              <button type="button" onClick={() => { setAuthMode('register'); setAuthError(''); }} className={`flex-1 py-2.5 text-xs font-bold rounded-lg ${authMode === 'register' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500'}`}>Register</button>
            </div>

            {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 text-xs rounded-lg font-semibold">{authError}</div>}

            <form onSubmit={authMode === 'signin' ? handleLogin : handleRegister} className="space-y-4">
              {authMode === 'register' && (
                <div>
                  <label className="block text-xs font-bold text-gray-700 mb-1">Full Name</label>
                  <input type="text" value={nameInput} onChange={e => setNameInput(e.target.value)} placeholder="Maya Sharma" className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" required />
                </div>
              )}
              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Email</label>
                <input type="email" value={emailInput} onChange={e => setEmailInput(e.target.value)} placeholder="you@canteen.org" className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" required />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Password</label>
                <input type="password" value={passwordInput} onChange={e => setPasswordInput(e.target.value)} placeholder="••••••••" className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" required />
              </div>
              {authMode === 'register' && (
                <div>
                  <label className="block text-xs font-bold text-gray-700 mb-1">I am joining as</label>
                  <select value={roleInput} onChange={e => setRoleInput(e.target.value)} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm bg-white">
                    <option value="Admin / Canteen manager">Admin / Canteen manager</option>
                    <option value="Recipient / NGO">Recipient / NGO</option>
                  </select>
                </div>
              )}
              <button type="submit" className="w-full py-3.5 bg-[#142A1E] hover:bg-[#1E3B2C] text-white font-bold rounded-xl text-sm mt-2">{authMode === 'signin' ? 'Sign in' : 'Create account'}</button>
            </form>

            <div className="relative my-6"><div className="absolute inset-0 flex items-center"><div className="w-full border-t border-gray-100"></div></div></div>

            <button type="button" onClick={handleDemoAccess} className="w-full py-3.5 bg-white border border-gray-200 hover:bg-gray-50 text-gray-800 font-semibold rounded-xl text-sm shadow-sm">✨ Continue with demo access</button>
          </div>
        </div>
      </div>
    );
  }

  // --- DASHBOARD VIEW ---
  return (
    <div className="flex min-h-screen bg-[#F4F6F4] text-gray-800 font-sans">
      <aside className="w-72 bg-[#142A1E] text-white flex flex-col justify-between p-6 shrink-0">
        <div>
          <div className="mb-8 pt-2">
            <p className="text-[10px] font-bold tracking-widest text-gray-400 uppercase mb-1">WORKSPACE</p>
            <p className="text-xl font-bold tracking-tight text-white">PlateAI</p>
          </div>
          <nav className="space-y-1">
            {['Overview', 'Demand forecast', 'Meals & attendance', 'Surplus food', 'Recipients', 'Impact analytics'].map((item) => {
              const id = item.toLowerCase().split(' ')[0];
              return (
                <button key={item} onClick={() => setActiveTab(id)} className={`w-full text-left px-4 py-3 rounded-xl text-sm font-semibold transition-colors ${activeTab === id ? 'bg-[#1E3B2C] text-white' : 'text-gray-400 hover:text-white'}`}>
                  {item}
                </button>
              );
            })}
          </nav>
        </div>

        <div className="pt-6 border-t border-[#1E3B2C]">
          <div className="flex items-center gap-3 mb-4">
            <div className="w-10 h-10 rounded-full bg-[#1A7B48] text-white font-bold flex items-center justify-center text-sm">
              {currentUser?.name ? currentUser.name.split(' ').map(n => n[0]).join('') : 'MS'}
            </div>
            <div>
              <p className="text-xs font-bold text-white">{currentUser?.name || 'Maya Sharma'}</p>
              <p className="text-[11px] text-gray-400">Canteen manager</p>
            </div>
          </div>
          <button onClick={handleLogout} className="flex items-center gap-2 text-xs text-gray-400 hover:text-white transition-colors">
            <span>←</span> Sign out
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0">
        <header className="bg-[#F4F6F4] px-10 py-6 flex justify-between items-center">
          <div>
            <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest">PLATEAI WORKSPACE</p>
          </div>
          <div className="flex items-center gap-4">
            <button className="w-9 h-9 rounded-full bg-white border border-gray-200 flex items-center justify-center text-gray-600 shadow-sm">🔔</button>
            <select className="border border-gray-200 rounded-xl px-4 py-2 text-sm bg-white font-semibold text-gray-700 shadow-sm">
              <option>Admin view</option>
              <option>Recipient view</option>
            </select>
          </div>
        </header>

        <main className="flex-1 px-10 pb-12 overflow-y-auto">
          {forecastMessage && (
            <div className="mb-6 p-4 bg-emerald-50 text-[#1A7B48] text-xs font-bold rounded-xl border border-emerald-100 flex items-center justify-between">
              <span>{forecastMessage}</span>
            </div>
          )}

          {/* DEMAND FORECAST TAB */}
          {activeTab === 'demand' && (
            <div className="space-y-6">
              <div className="flex justify-between items-start">
                <div>
                  <h1 className="text-3xl lg:text-4xl font-extrabold tracking-tight text-gray-900 mb-2">Demand, made explainable.</h1>
                  <p className="text-gray-500 text-sm">Turn attendance and weather signals into a preparation decision your team can act on.</p>
                </div>
                <button onClick={handleSyncWeather} className="px-4 py-2.5 bg-white border border-gray-200 hover:bg-gray-50 rounded-xl text-xs font-bold text-gray-800 shadow-sm flex items-center gap-2 shrink-0">
                  <span>🔄</span> Sync live weather
                </button>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
                  <div className="flex justify-between items-center mb-6">
                    <div>
                      <h3 className="text-base font-bold text-gray-900">Build a forecast</h3>
                      <p className="text-xs text-gray-400">Local model + GPT-5.4 planning note</p>
                    </div>
                    <span className="px-3 py-1 bg-emerald-50 text-[#1A7B48] text-xs font-bold rounded-full flex items-center gap-1">✨ Explainable</span>
                  </div>

                  <form onSubmit={handleCalculateForecast} className="space-y-5">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Expected attendance</label>
                        <input type="number" value={forecastData.expectedAttendance} onChange={e => setForecastData({...forecastData, expectedAttendance: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Day</label>
                        <select value={forecastData.day} onChange={e => setForecastData({...forecastData, day: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm bg-white">
                          <option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option><option>Sunday</option>
                        </select>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Meal type</label>
                        <select value={forecastData.mealType} onChange={e => setForecastData({...forecastData, mealType: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm bg-white">
                          <option>Lunch</option><option>Dinner</option><option>Breakfast</option>
                        </select>
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Safety buffer · meals</label>
                        <input type="number" value={forecastData.safetyBuffer} onChange={e => setForecastData({...forecastData, safetyBuffer: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Temperature · °C</label>
                        <input type="number" value={forecastData.temperature} onChange={e => setForecastData({...forecastData, temperature: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Rainfall · mm</label>
                        <input type="number" value={forecastData.rainfall} onChange={e => setForecastData({...forecastData, rainfall: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2">
                      <label className="flex items-center gap-3 p-3.5 border border-gray-200 rounded-xl cursor-pointer hover:bg-gray-50">
                        <input type="checkbox" checked={forecastData.holiday} onChange={e => setForecastData({...forecastData, holiday: e.target.checked})} className="w-4 h-4 accent-[#1A7B48]" />
                        <span className="text-xs font-bold text-gray-800">Holiday</span>
                      </label>
                      <label className="flex items-center gap-3 p-3.5 border border-gray-200 rounded-xl cursor-pointer hover:bg-gray-50">
                        <input type="checkbox" checked={forecastData.campusEvent} onChange={e => setForecastData({...forecastData, campusEvent: e.target.checked})} className="w-4 h-4 accent-[#1A7B48]" />
                        <span className="text-xs font-bold text-gray-800">Campus event</span>
                      </label>
                    </div>

                    <button type="submit" className="w-full sm:w-auto px-6 py-3.5 bg-[#142A1E] hover:bg-[#1E3B2C] text-white font-bold rounded-xl text-sm mt-4 flex items-center justify-center gap-2">
                      <span>⚡</span> Calculate preparation plan
                    </button>
                  </form>
                </div>

                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex flex-col justify-between">
                  <div>
                    <p className="text-[10px] font-bold tracking-widest text-[#1A7B48] uppercase mb-1">LIVE CONTEXT</p>
                    <h3 className="text-base font-bold text-gray-900 mb-2">Weather at campus</h3>
                    <p className="text-xs text-gray-500 mb-6">Weather is an input signal, not a verdict. Refresh it before a new service plan.</p>

                    <div className="flex items-center gap-3 mb-6">
                      <span className="text-4xl">☀️</span>
                      <div>
                        <p className="text-3xl font-extrabold text-gray-900">{forecastData.weatherContext?.temp || forecastData.temperature}°</p>
                        <p className="text-xs text-gray-500">{forecastData.weatherContext?.condition || 'Demo clear weather'}</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 pt-4 border-t border-gray-100">
                      <div>
                        <span className="text-[11px] font-semibold text-gray-400 block mb-1">Rainfall</span>
                        <p className="text-base font-bold text-gray-900">{forecastData.weatherContext?.rainfall || `${forecastData.rainfall} mm`}</p>
                      </div>
                      <div>
                        <span className="text-[11px] font-semibold text-gray-400 block mb-1">Humidity</span>
                        <p className="text-base font-bold text-gray-900">{forecastData.weatherContext?.humidity || '62%'}</p>
                      </div>
                    </div>
                  </div>

                  <p className="text-[10px] text-gray-400 uppercase tracking-wider mt-6">SOURCE · Open-Meteo API</p>
                </div>
              </div>

              {/* RECOMMENDATION READY PANEL */}
              {calculatedPlan && (
                <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-200 mt-8">
                  <div className="flex justify-between items-start mb-6">
                    <div>
                      <p className="text-[10px] font-bold tracking-widest text-[#1A7B48] uppercase mb-1">RECOMMENDATION READY</p>
                      <h3 className="text-2xl font-extrabold text-gray-900">Tomorrow’s preparation plan</h3>
                    </div>
                    <span className="px-3 py-1 bg-emerald-50 text-[#1A7B48] text-xs font-bold rounded-full flex items-center gap-1">✓ Saved</span>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
                    <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100">
                      <span className="text-xs font-semibold text-gray-500 block mb-2">Predicted demand</span>
                      <p className="text-3xl font-extrabold text-gray-900">{calculatedPlan.predictedDemand}</p>
                      <span className="text-xs text-gray-500 mt-1 block">meals</span>
                    </div>
                    <div className="bg-[#F2F8EE] p-5 rounded-2xl border border-[#D5EAD0]">
                      <span className="text-xs font-semibold text-[#1A7B48] block mb-2">Recommended preparation</span>
                      <p className="text-3xl font-extrabold text-[#1A7B48]">{calculatedPlan.recommendedPrep}</p>
                      <span className="text-xs font-bold text-[#1A7B48] mt-1 block">{calculatedPlan.buffer} meal buffer</span>
                    </div>
                    <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100">
                      <span className="text-xs font-semibold text-gray-500 block mb-2">Planning model</span>
                      <p className="text-xl font-bold text-gray-900">Local + AI</p>
                      <span className="text-xs text-[#1A7B48] font-bold mt-1 block">GPT-5.4</span>
                    </div>
                    <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100">
                      <span className="text-xs font-semibold text-gray-500 block mb-2">Weather input</span>
                      <p className="text-xl font-bold text-gray-900">{calculatedPlan.temperature}°C</p>
                      <span className="text-xs text-gray-500 mt-1 block">{calculatedPlan.rainfall} mm rain</span>
                    </div>
                  </div>

                  <div className="p-4 bg-[#F8FBF6] rounded-xl border-l-4 border-[#1A7B48] flex items-start gap-3">
                    <span className="text-base text-[#1A7B48]">✨</span>
                    <div>
                      <span className="text-xs font-bold text-gray-900">AI planning note: </span>
                      <span className="text-xs text-gray-700 leading-relaxed">{calculatedPlan.planningNote}</span>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* OVERVIEW TAB */}
          {activeTab === 'overview' && (
            <div className="space-y-6">
              <div>
                <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest">{overviewData?.greetingDate || 'WEDNESDAY · 18 MARCH 2026'}</p>
                <h2 className="text-xl font-extrabold text-gray-900">Good morning, {currentUser?.name ? currentUser.name.split(' ')[0] : 'Maya'}</h2>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                  <span className="text-xs font-semibold text-gray-400 block mb-2">Expected demand</span>
                  <p className="text-2xl font-bold text-gray-900">{overviewData?.expectedDemand || '407 meals'}</p>
                </div>
                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                  <span className="text-xs font-semibold text-gray-400 block mb-2">Recommended prep</span>
                  <p className="text-2xl font-bold text-gray-900">{overviewData?.recommendedPrep || '422 meals'}</p>
                </div>
                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                  <span className="text-xs font-semibold text-gray-400 block mb-2">Actual consumption</span>
                  <p className="text-2xl font-bold text-gray-900">{overviewData?.actualConsumption || '410 meals'}</p>
                </div>
                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                  <span className="text-xs font-semibold text-gray-400 block mb-2">Safe surplus</span>
                  <p className="text-2xl font-bold text-gray-900">{overviewData?.safeSurplus || '60 meals'}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                  <div className="flex justify-between items-start mb-6">
                    <div>
                      <h3 className="text-base font-bold text-gray-900">Predicted vs actual consumption</h3>
                      <p className="text-xs text-gray-400">Last six service days · meals</p>
                    </div>
                    <div className="flex items-center gap-4 text-xs font-semibold text-gray-600">
                      <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-[#1A7B48]"></span> Predicted</span>
                      <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-[#D4E035]"></span> Actual</span>
                    </div>
                  </div>

                  <div className="h-44 relative flex items-end justify-between pt-6 px-4">
                    <div className="absolute inset-0 flex flex-col justify-between pointer-events-none opacity-20">
                      <div className="border-b border-gray-200 w-full text-[10px] text-right">600</div>
                      <div className="border-b border-gray-200 w-full text-[10px] text-right">450</div>
                      <div className="border-b border-gray-200 w-full text-[10px] text-right">300</div>
                      <div className="border-b border-gray-200 w-full"></div>
                    </div>
                    {overviewData?.chartDays?.map((d, i) => (
                      <div key={i} className="z-10 flex flex-col items-center flex-1 h-full justify-end group">
                        <div className="w-full flex justify-center items-end gap-1 h-32">
                          <div style={{ height: `${(d.predicted / 600) * 100}%` }} className="w-2 bg-[#1A7B48] rounded-t-sm"></div>
                          <div style={{ height: `${(d.actual / 600) * 100}%` }} className="w-2 bg-[#D4E035] rounded-t-sm"></div>
                        </div>
                        <span className="text-xs font-medium text-gray-400 mt-2">{d.day}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex flex-col justify-between">
                  <div>
                    <h3 className="text-base font-bold text-gray-900 mb-4">Signals to act on</h3>
                    <div className="space-y-4">
                      {overviewData?.signals?.map((s, idx) => (
                        <div key={idx} className="p-3.5 bg-[#F8F9F8] rounded-xl border border-gray-100 flex items-start gap-3">
                          <span className="text-base">🔔</span>
                          <div>
                            <p className="text-xs font-bold text-gray-900">{s.title}</p>
                            <p className="text-[11px] text-gray-500 mt-0.5">{s.subtitle}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab !== 'overview' && activeTab !== 'demand' && (
            <div className="bg-white p-12 rounded-2xl shadow-sm border border-gray-100 text-center">
              <h2 className="text-2xl font-bold text-gray-800 capitalize mb-2">{activeTab.replace('-', ' ')}</h2>
              <p className="text-gray-500 text-sm">Module is active and ready.</p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

export default App;
